<label>Nome completo<input name="name" value="{{$professor->name ?? ''}}" required></label><label>E-mail<input type="email" name="email" value="{{$professor->email ?? ''}}" required></label><label>Senha {{$professor ? '(deixe em branco para manter)' : ''}}<input type="password" name="password" minlength="8" @required(! $professor) autocomplete="new-password"></label><label>Situação<select name="ativo"><option value="1" @selected($professor?->ativo ?? true)>Ativo</option><option value="0" @selected($professor && ! $professor->ativo)>Inativo</option></select></label><fieldset><legend>Turmas responsáveis</legend>@foreach($turmas as $turma)<label><input style="width:auto" type="checkbox" name="turmas[]" value="{{$turma->id}}" @checked($professor && $professor->turmas->contains($turma))> {{$turma->nome}} — {{$turma->ano_letivo}} / {{$turma->curso}}</label>@endforeach</fieldset>
